function solve(s) {
  const n = s.length;
  let out = "";
  for (let i = 0; i < n; i++) {
    if (i > 0 && s[i] === s[i - 1]) continue;
    let run = 1;
    while (i + run < n) {
      let same = true;
      for (let t = i; t <= i + run; t++) {
        if (s[t] !== s[i]) {
          same = false;
          break;
        }
      }
      if (!same) break;
      run++;
    }
    out += s[i];
    if (run > 1) out += String(run);
  }
  return out;
}

function solve(s) {
  const n = s.length;
  let out = "";
  let i = 0;
  while (i < n) {
    let j = i;
    while (j < n && s[j] === s[i]) j++;
    const run = j - i;
    out += s[i];
    if (run > 1) out += String(run);
    i = j;
  }
  return out;
}
